entries[90531] = { ["name"] = "Pläne: Geistereisenschildstachel", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Geistereisenschildstachel.\nBenötigt Schmiedekunst von Pandaria (15)\nBenötigt Die Klaxxi\n- Wohlwollend\n\nGeistereisenschildstachel\nWird beim Anlegen gebunden\nBenutzen: Bringt einen Geistereisenstachel an Eurem Schild an, der beim Blocken manchmal 42 Schaden verursacht.\n\nDurch das Anbringen des Geistereisenstachels wird der Gegenstand seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:\nBenötigt Geistereisenbarren (12)" }
entries[90532] = { ["name"] = "Pläne: Waffenkette aus lebendigem Stahl", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer Waffenkette aus lebendigem Stahl.\nBenötigt Schmiedekunst von Pandaria (15)\nBenötigt Die Klaxxi\n- Wohlwollend\n\nWaffenkette aus lebendigem Stahl\nWird beim Anlegen gebunden\nBenutzen: Bringt eine Kette an Eurer Waffe an, die die Wirkungsdauer von Entwaffnungseffekten um 50% verringert und Euren kritischen Trefferwert um 13 erhöht. Ist nicht mit ähnlichen Effekten stapelbar. Durch das Anbringen der Waffenkette wird der Gegenstand seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Lebendiger Stahl" }
