entries[90655] = { ["name"] = "Zügel der donnernden Rubinwolkenschlange", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört eine reitbare donnernde Rubinwolkenschlange oder gibt sie wieder frei. Das ist ein Flugreittier. Benötigt 'Wolkenschlangenreiten' vom Orden der Wolkenschlange.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Von Geburt an fühlen sich donnernde Wolkenschlangen zu Stürmen hingezogen. Sie jagen gerne Blitze durch dunkle, trübe Wolken und lassen Regengüsse auf sich prasseln.\"\nBeute von:\nAlani\nZone:\nTal der Ewigen Blüten" }
entries[90659] = { ["name"] = "Jasmintee", ["text"] = "Benutzen: Stellt im Verlauf von 21 Sek. insgesamt ( 90 / 5 * 21) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\nVerkaufspreis:" }
entries[90660] = { ["name"] = "Schwarzer Tee", ["text"] = "Benutzen: Stellt im Verlauf von 24 Sek. insgesamt ( 45 / 5 * 24) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\nVerkaufspreis:" }
entries[90710] = { ["name"] = "Zügel des aschegrauen Pandarenphönix", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren purpurroter Pandarenphönix und gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Sowohl der Name als auch die Farbe dieses majestätischen Phönix sollen die Wiedergeburt symbolisieren.\"\nVerkäufer:\nWeltverkäufer\nKosten:\n1" }
entries[90711] = { ["name"] = "Zügel des smaragdgrünen Pandarenphönix", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren smaragdgrünen Pandarenphönix und gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Gefiederfarben dieses seltenen Phönix sollen großes Glück bringen.\"\nVerkäufer:\nWeltverkäufer\nKosten:\n1" }
entries[90712] = { ["name"] = "Zügel des violetten Pandarenphönix", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren violetten Pandarenphönix und gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Das Gefieder des violetten Phönix soll die Vereinigung gegensätzlicher Kräfte symbolisieren.\"\nVerkäufer:\nWeltverkäufer\nKosten:\n1" }
