entries[91789] = { ["name"] = "Plattenbeinschützer des bösartigen Gladiators", ["text"] = "Saison 13\nWird beim Aufheben gebunden\nBeine Platte\n14 Rüstung\n+2 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 1.\n\nPrismatischer Sockel\nPrismatischer Sockel\nSockelbonus: + 4 Vielseitigkeit\n\nHaltbarkeit 120 / 120\nKlassen: Krieger\nSchlachtrüstung des Gladiators (0/5)\nPlattenbrustharnisch des Gladiators\nPlattenstulpen des Gladiators\nPlattenhelm des Gladiators\nPlattenbeinschützer des Gladiators\nPlattenschultern des Gladiators\nAltes Set: Bonus ist nicht aktiv\n(2) Set : Erhöht Euren gesamten verursachten Schaden um 4%.\n(4) Set : Tempo um 5% erhöht.\nVerkaufspreis:" }
entries[91791] = { ["name"] = "Plattenschultern des bösartigen Gladiators", ["text"] = "Saison 13\nWird beim Aufheben gebunden\nSchulter Platte\n11 Rüstung\n+2 [Stärke oder Intelligenz]\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 3.\n\nPrismatischer Sockel\nSockelbonus: + 2 Stärke\n\nHaltbarkeit 100 / 100\nKlassen: Krieger\nSchlachtrüstung des Gladiators (0/5)\nPlattenbrustharnisch des Gladiators\nPlattenstulpen des Gladiators\nPlattenhelm des Gladiators\nPlattenbeinschützer des Gladiators\nPlattenschultern des Gladiators\nAltes Set: Bonus ist nicht aktiv\n(2) Set : Erhöht Euren gesamten verursachten Schaden um 4%.\n(4) Set : Tempo um 5% erhöht.\nVerkaufspreis:" }
entries[91802] = { ["name"] = "Jadegrüne pandarische Drachenleine", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Pandarendrachen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die Bewohner von Pandaria bewundern Euren Enthusiasmus für die Erhaltung der Tierwelt. Sie machen sich jedoch Sorgen darum, wie sie bei jedem Besuch 150 Tiere versorgen sollen.\"\nErfolg:\nWir brauchen mehr Sättel\nKategorie:\nAllgemein" }
entries[91803] = { ["name"] = "Schnappwurzknolle", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erhöht das Tempo 25 Sek. lang um 182 . (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[91806] = { ["name"] = "Instabiler Portalsplitter", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: \"Pflanzt\" den instabilen Portalsplitter ein.\n\"Kristalle aus chaotischer Arkanenergie von stark frequentierten Portalen. Die Erde des Gehöfts Sonnensang stabilisiert diese Energie und erzeugt einen Splitter, der auf dem Gehöft zerbrochen werden kann, um ein Einwegportal zu einer Hauptstadt zu öffnen.\"\nVerkaufspreis:" }
entries[91807] = { ["name"] = "Kopf von Or", ["text"] = "Questgegenstand\n\"Die Überraschung ob seiner Niederlage steht immer noch in Ors Gesicht geschrieben – eines seiner Gesichter zumindest.\"" }
entries[91808] = { ["name"] = "Kopf von Dac", ["text"] = "Questgegenstand\n\"Selbst im Tod streckt Euch Dac noch seine Zunge entgegen.\"" }
entries[91809] = { ["name"] = "Kopf von Ruk'ra", ["text"] = "Questgegenstand\n\"Ein Ausdruck typischen Kor'kronstolzes und -trotzes lässt sich noch immer in dieser Grimasse erkennen.\"" }
entries[91810] = { ["name"] = "Kopf von Klitzefritz", ["text"] = "Questgegenstand\n\"Hat immer noch die Gasmaske auf.\"" }
entries[91814] = { ["name"] = "Makellose goldene Kronenfeder", ["text"] = "Questgegenstand\n\"Eine absolut saubere, frische Feder eines Kindes von Chi-Ji.\"" }
entries[91815] = { ["name"] = "Makellose schwarze Kronenfeder", ["text"] = "Questgegenstand\n\"Eine pechschwarze Feder eines großen Kranichs.\"" }
entries[91816] = { ["name"] = "Unbeschädigte Yakkeule", ["text"] = "Questgegenstand\n\"Fettes Yakfleisch. Der Traum eines jeden Tigergaumens.\"" }
entries[91817] = { ["name"] = "Müffelnder verrotteter Fisch", ["text"] = "Questgegenstand\n\"Der Geruch ist... überwältigend.\"" }
entries[91819] = { ["name"] = "Robuste Kranichschlinge", ["text"] = "Wird bei Benutzung gebunden\nEinzigartig: Robuste Falle (1)\nDieser Gegenstand startet eine Quest.\n\"Eine fachmännisch geknotete Schlinge, der selbst ein kräftiges Kranichbein nicht entkommen kann.\"" }
entries[91821] = { ["name"] = "Robuste Tigerfalle", ["text"] = "Wird bei Benutzung gebunden\nEinzigartig: Robuste Falle (1)\nDieser Gegenstand startet eine Quest.\n\"Eine stramm gezurrte Falle, mit der extragroße Tiger gefangen und bewegungsunfähig gemacht werden können.\"" }
entries[91822] = { ["name"] = "Robuster Krabbenkorb", ["text"] = "Wird bei Benutzung gebunden\nEinzigartig: Robuste Falle (1)\nDieser Gegenstand startet eine Quest.\n\"Ein widerstandsfähiger Korb, mit dem extragroße Krabben gefangen werden können.\"" }
entries[91823] = { ["name"] = "Belebbarer Stein", ["text"] = "Questgegenstand\n\"Dieser Stein scheint zu vibrieren, wenn Ihr ihn berührt.\"" }
entries[91834] = { ["name"] = "Uralter Blutkronenkranich", ["text"] = "Questgegenstand\n\"Der betäubte Körper eines großen, kräftigen Kranichs.\"" }
entries[91835] = { ["name"] = "Alter Krasaritiger", ["text"] = "Questgegenstand\n\"Der betäubte Körper eines großen, kräftigen Tigers.\"" }
entries[91836] = { ["name"] = "Kolossale Zwingzange", ["text"] = "Questgegenstand\n\"Der betäubte Körper einer großen, kräftigen Krabbe.\"" }
entries[91838] = { ["name"] = "Schlachtbefehl der Löwenlandung", ["text"] = "Wird beim Aufheben gebunden\n\"Dieser Schlachtbefehl war für Mitglieder der Allianz bestimmt, die in der Löwenlandung ihren Dienst leisten. Bringt sie zu Ongrom Schwarzzahn bei der Herrschaftsfeste.\"" }
entries[91846] = { ["name"] = "Fass mit \"destilliertem\" Treibstoff", ["text"] = "Questgegenstand\n\"Eine Mischung aus übelriechendem Meerwasser und Treibstoff schwappt in diesem Fass herum.\"" }
entries[91848] = { ["name"] = "Aufgeladener Eisenerzbrocken", ["text"] = "Questgegenstand\n\"Das Erz pulsiert vor dunkler Energie. Das kann nichts Gutes bedeuten...\"" }
entries[91850] = { ["name"] = "Portalsplitter: Orgrimmar", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bricht den Splitter auf und erschafft ein Portal nach Orgrimmar.\n\nKann nur auf dem Gehöft Sonnensang verwendet werden." }
entries[91854] = { ["name"] = "Robuste Kranichschlinge", ["text"] = "Wird bei Benutzung gebunden\nEinzigartig: Robuste Falle (1)\nDieser Gegenstand startet eine Quest.\n\"Eine fachmännisch geknotete Schlinge, der selbst ein kräftiges Kranichbein nicht entkommen kann.\"" }
entries[91855] = { ["name"] = "Robuste Tigerfalle", ["text"] = "Wird bei Benutzung gebunden\nEinzigartig: Robuste Falle (1)\nDieser Gegenstand startet eine Quest.\n\"Eine stramm gezurrte Falle, mit der extragroße Tiger gefangen und bewegungsunfähig gemacht werden können.\"" }
entries[91856] = { ["name"] = "Robuster Krabbenkorb", ["text"] = "Wird bei Benutzung gebunden\nEinzigartig: Robuste Falle (1)\nDieser Gegenstand startet eine Quest.\n\"Ein widerstandsfähiger Korb, mit dem extragroße Krabben gefangen werden können.\"" }
entries[91860] = { ["name"] = "Portalsplitter: Sturmwind", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bricht den Splitter auf und erschafft ein Portal nach Sturmwind.\n\nKann nur auf dem Gehöft Sonnensang verwendet werden." }
entries[91861] = { ["name"] = "Portalsplitter: Donnerfels", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bricht den Splitter auf und erschafft ein Portal nach Donnerfels.\n\nKann nur auf dem Gehöft Sonnensang verwendet werden." }
entries[91862] = { ["name"] = "Portalsplitter: Unterstadt", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bricht den Splitter auf und erschafft ein Portal nach Unterstadt.\n\nKann nur auf dem Gehöft Sonnensang verwendet werden." }
entries[91863] = { ["name"] = "Portalsplitter: Silbermond", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bricht den Splitter auf und erschafft ein Portal nach Silbermond.\n\nKann nur auf dem Gehöft Sonnensang verwendet werden." }
entries[91864] = { ["name"] = "Portalsplitter: Eisenschmiede", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bricht den Splitter auf und erschafft ein Portal nach Eisenschmiede.\n\nKann nur auf dem Gehöft Sonnensang verwendet werden." }
entries[91865] = { ["name"] = "Portalsplitter: Darnassus", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bricht den Splitter auf und erschafft ein Portal nach Darnassus.\n\nKann nur auf dem Gehöft Sonnensang verwendet werden." }
entries[91866] = { ["name"] = "Portalsplitter: Exodar", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bricht den Splitter auf und erschafft ein Portal zur Exodar.\n\nKann nur auf dem Gehöft Sonnensang verwendet werden." }
entries[91869] = { ["name"] = "Verdorbenes Zwingzangenfleisch", ["text"] = "Questgegenstand\n\"Ein ranziger Gestank geht von diesem eitrigen Fleisch aus.\"" }
entries[91871] = { ["name"] = "Gezackter Stein", ["text"] = "Questgegenstand\n\"Der Stein hat eine rauhe, aber warme Oberfläche.\"" }
entries[91874] = { ["name"] = "Brocken eigenartiges Fleisch", ["text"] = "Questgegenstand\n\"Ein fürchterlich riechender Schleim trieft von dem Fleisch. Es wird Tage dauern, bis Ihr den Gestank aus Euren Taschen bekommt.\"" }
entries[91875] = { ["name"] = "Kreissäges Hausmarke", ["text"] = "Questgegenstand\nEinzigartig\n\"Bixis geheimes Familienrezept für Treibstoff, das von einer Generation Kreissägen zur nächsten weitergegeben wurde.\"" }
entries[91877] = { ["name"] = "Schlachtbefehl der Herrschaftsfeste", ["text"] = "Wird beim Aufheben gebunden\n\"Ein kleines Schriftstück, das in der Sprache der Orcs verfasst ist und eine Karte von Pandaria zeigt, auf der mit roter Tinte Punkte markiert sind. Bringt es zu Administrator Grantley in der Löwenlandung.\"" }
entries[91902] = { ["name"] = "Universalfernsteuerung", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Sendet auf Frequenz Drei Zwo Neun. (5 Sek. Abklingzeit)\n\"Nicht direkt in die Lichtquelle blicken. Hersteller übernimmt keine Haftbarkeit.\"" }
entries[91904] = { ["name"] = "Stapelbarer Hirsch", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört einen stapelbaren Hirsch am Zielort. Wenn sich ein anderer stapelbarer Hirsch in der Nähe befindet, wird sich Euer stapelbarer Hirsch auf den anderen stapelbaren Hirsch stapeln. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[91906] = { ["name"] = "Brüchige Wurzel", ["text"] = "Ein wenig Geduld\nEinzigartig (5)\nBenutzen: Stellt allen Arbeitern Materialien zur Verfügung, wodurch sich ihre Arbeitsgeschwindigkeit 60 Sek. lang um 30% des Grundwerts erhöht. Bis zu 3-mal stapelbar." }
entries[91907] = { ["name"] = "Bauholz der Löwenlandung", ["text"] = "Questgegenstand\n\"Dieses Holz wurde kürzlich in den Wäldern um die Löwenlandung geschlagen – und noch kürzlicher von feigen Arbeitern zurückgelassen.\"" }
entries[91971] = { ["name"] = "Kampfrationen", ["text"] = "Ein wenig Geduld\nEinzigartig (5)\nBenutzen: Versorgt alle Arbeiter mit Nahrung, was ihre Arbeitsgeschwindigkeit 60 Sek. lang um 60% des Grundwerts erhöht. Bis zu 3-mal stapelbar." }
entries[92019] = { ["name"] = "Der Bilgewässer Molotow", ["text"] = "Questgegenstand\nBenutzen: Wirft eine Flasche brennenden, umfunktionierten Fusels nach einem Gyrokopter X2 der Himmelsfeuer.\n\"Ein starkes Gemisch aus hochreaktiven, brennbaren Chemikalien, serviert mit einem brennenden Taschentuch.\"" }
entries[92035] = { ["name"] = "Verziertes Zepter", ["text"] = "Ein wenig Geduld\nEinzigartig\n\"Ein uraltes Moguartefakt.\"" }
entries[92036] = { ["name"] = "Stab des Affenkönigs", ["text"] = "Questgegenstand\n\"Ihr verspürt große Macht in diesem einfach anmutenden Stab. So sehr Ihr es auch versucht, er lässt sich nicht benutzen.\"\nVerkaufspreis:" }
entries[92049] = { ["name"] = "Söldnervertrag: Magier", ["text"] = "Benutzen: Heuert einen Magier an, der Hordespielern in der Nähe kostenlos 'Arkane Brillanz' verleiht.\n\nArkane Brillanz\n30 Meter Reichweite\nSofort\nRequires Mage Erfüllt das Ziel mit Brillanz, erhöht 1 Stunde lang seine Zaubermacht um 10% und seine kritische Trefferchance um 5%. Funktioniert nur in der Krasarangwildnis." }
entries[92050] = { ["name"] = "Söldnervertrag: Paladin", ["text"] = "Benutzen: Heuert einen Paladin an, der Hordespielern in der Nähe kostenlos 'Segen der Macht' verleiht.\n\nSegen der Macht Stufe 35 30 Meter Reichweite\nSofort\nRequires Paladin Belegt ein befreundetes Ziel mit einem Segen, welcher seine Meisterschaft um 59 erhöht. Funktioniert nur in der Krasarangwildnis." }
entries[92051] = { ["name"] = "Söldnervertrag: Priester", ["text"] = "Benutzen: Heuert einen Priester an, der Hordespielern in der Nähe kostenlos 'Machtwort: Seelenstärke' verleiht.\n\nMachtwort: Seelenstärke 4.4% of base mana 40 Meter Reichweite Spontan\nRequires Priest Erfüllt das Ziel mit Vitalität, die die Ausdauer 1 Stunde lang um 10% erhöht. Funktioniert nur in der Krasarangwildnis." }
entries[92052] = { ["name"] = "Söldnervertrag: Druide", ["text"] = "Benutzen: Heuert einen Druiden an, der Hordespielern in der Nähe kostenlos 'Mal der Wildnis' verleiht.\n\nMal der Wildnis\n30 Meter Reichweite\nSofort\nRequires Druid Erhöht die Stärke, Beweglichkeit und Intelligenz des verbündeten Ziels 1 Stunde lang um 5%. Funktioniert nur in der Krasarangwildnis." }
entries[92053] = { ["name"] = "Söldnervertrag: Krieger", ["text"] = "Benutzen: Heuert einen Krieger an, der Hordespielern in der Nähe kostenlos 'Schlachtruf' verleiht.\n\nGellender Schlachtruf\n30 Meter Reichweite\nSofort\nRequires Warrior Erhöht die Angriffskraft des Ziels um 10%. Funktioniert nur in der Krasarangwildnis." }
entries[92054] = { ["name"] = "Söldnervertrag: Schurke", ["text"] = "Benutzen: Heuert einen Schurken an, der Hordespielern in der Nähe kostenlos 'Signal der Schnellklinge' verleiht.\n\nSignal der Schnellklinge\n30 Meter Reichweite\nSofort\nRequires Rogue Erhöht das Nahkampf- und Distanzangriffstempo des Ziels um 10%. Funktioniert nur in der Krasrangwildnis." }
entries[92055] = { ["name"] = "Söldnervertrag: Schamane", ["text"] = "Benutzen: Heuert einen Schamanen an, der Hordespielern in der Nähe kostenlos 'Bindender elementarer Schwur' verleiht.\n\nBindender Elementarer Schwur\n30 Meter Reichweite\nSofort\nRequires Shaman Gewährt dem Ziel 5% Zaubertempo. Funktioniert nur in der Krasarangwildnis." }
