entries[92070] = { ["name"] = "Ranzen der Huojin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n16 Platz Tasche\n\"Erfordert einen respektvollen Ruf bei den Huojin.\"" }
entries[92071] = { ["name"] = "Ranzen der Tushui", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n16 Platz Tasche\n\"Erfordert einen respektvollen Ruf bei den Tushui.\"" }
entries[92072] = { ["name"] = "Korunkodex", ["text"] = "Questgegenstand\n\"Auf dem ledrigen Pergament ist eine Karte der nordöstlichen Kun-Lai-Berge abgebildet. Uralte, in dunkelroter Tinte gezeichnete Symbole der Macht gehen vom Mittelpunkt der Karte nach außen.\"" }
entries[92421] = { ["name"] = "Bewachungsvertrag: Friedhof", ["text"] = "Benutzen: Heuert Wachen an, die einen eroberbaren Friedhof in der Krasarangwildnis bewachen. Ihr müsst Euch in der Nähe des Friedhofs befinden und Eure Fraktion muss ihn kontrollieren." }
