entries[92433] = { ["name"] = "Söldnervertrag: Schamane", ["text"] = "Benutzen: Heuert einen Schamanen an, der Allianzspielern in der Nähe kostenlos 'Bindender elementarer Schwur' verleiht.\n\nBindender Elementarer Schwur\n30 Meter Reichweite\nSofort\nRequires Shaman Gewährt dem Ziel 5% Zaubertempo. Funktioniert nur in der Krasarangwildnis." }
entries[92434] = { ["name"] = "Söldnervertrag: Schurke", ["text"] = "Benutzen: Heuert einen Schurken an, der Allianzspielern in der Nähe kostenlos 'Signal der Schnellklinge' verleiht.\n\nSignal der Schnellklinge\n30 Meter Reichweite\nSofort\nRequires Rogue Erhöht das Nahkampf- und Distanzangriffstempo des Ziels um 10%. Funktioniert nur in der Krasrangwildnis." }
entries[92435] = { ["name"] = "Söldnervertrag: Krieger", ["text"] = "Benutzen: Heuert einen Krieger an, der Allianzspielern in der Nähe kostenlos 'Schlachtruf' verleiht.\n\nGellender Schlachtruf\n30 Meter Reichweite\nSofort\nRequires Warrior Erhöht die Angriffskraft des Ziels um 10%. Funktioniert nur in der Krasarangwildnis." }
entries[92436] = { ["name"] = "Söldnervertrag: Druide", ["text"] = "Benutzen: Heuert einen Druiden an, der Allianzspielern in der Nähe kostenlos 'Mal der Wildnis' verleiht.\n\nMal der Wildnis\n30 Meter Reichweite\nSofort\nRequires Druid Erhöht die Stärke, Beweglichkeit und Intelligenz des verbündeten Ziels 1 Stunde lang um 5%. Funktioniert nur in der Krasarangwildnis." }
entries[92437] = { ["name"] = "Söldnervertrag: Priester", ["text"] = "Benutzen: Heuert einen Priester an, der Allianzspielern in der Nähe kostenlos 'Machtwort: Seelenstärke' verleiht.\n\nMachtwort: Seelenstärke 4.4% of base mana 40 Meter Reichweite Spontan\nRequires Priest Erfüllt das Ziel mit Vitalität, die die Ausdauer 1 Stunde lang um 10% erhöht. Funktioniert nur in der Krasarangwildnis." }
entries[92438] = { ["name"] = "Söldnervertrag: Paladin", ["text"] = "Benutzen: Heuert einen Paladin an, der Allianzspielern in der Nähe kostenlos 'Segen der Macht' verleiht.\n\nSegen der Macht Stufe 35 30 Meter Reichweite\nSofort\nRequires Paladin Belegt ein befreundetes Ziel mit einem Segen, welcher seine Meisterschaft um 59 erhöht. Funktioniert nur in der Krasarangwildnis." }
entries[92439] = { ["name"] = "Söldnervertrag: Magier", ["text"] = "Benutzen: Heuert einen Magier an, der Allianzspielern in der Nähe kostenlos 'Arkane Brillanz' verleiht.\n\nArkane Brillanz\n30 Meter Reichweite\nSofort\nRequires Mage Erfüllt das Ziel mit Brillanz, erhöht 1 Stunde lang seine Zaubermacht um 10% und seine kritische Trefferchance um 5%. Funktioniert nur in der Krasarangwildnis." }
entries[92440] = { ["name"] = "Faksimile der Archäologischen Akademie", ["text"] = "\"Eine Abschrift der uralten Tafel der Korun. Darin wird der Ursprung der Götterglocke beschrieben.\"\n<Zum Lesen rechtsklicken>" }
entries[92441] = { ["name"] = "Kodex von Xerrath", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Als Ihr das Buch aufhebt, erklingen schreckliche, geflüsterte Mysterien in Euren Ohren, die Euren Verstand peinigen…\"" }
entries[92442] = { ["name"] = "Hordebanner", ["text"] = "Einzigartig (20)\nBenutzen: Stellt ein Hordenbanner auf. Das Banner bleibt 10 Minuten lang bestehen und ihr könnt bis zu 5 Banner gleichzeitig aufstellen.\n\nIhr müsst für PvP markiert sein, um ein Banner aufzustellen. Für PvP markierte Spielercharaktere der Allianz können versuchen, Eure Banner niederzubrennen." }
entries[92443] = { ["name"] = "Allianzbanner", ["text"] = "Einzigartig (20)\nBenutzen: Stellt ein Allianzbanner auf. Das Banner bleibt 10 Minuten lang bestehen und ihr könnt bis zu 5 Banner gleichzeitig aufstellen.\n\nIhr müsst für PvP markiert sein, um ein Banner aufzustellen. Für PvP markierte Spielercharaktere der Horde können versuchen, Eure Banner niederzubrennen." }
entries[92444] = { ["name"] = "Fleischige Keule", ["text"] = "Ein wenig Geduld\nEinzigartig (5)\nBenutzen: Versorgt alle Arbeiter mit Nahrung, was ihre Arbeitsgeschwindigkeit 60 Sek. lang um 60% des Grundwerts erhöht. Bis zu 3-mal stapelbar." }
entries[92470] = { ["name"] = "Schlangenöl", ["text"] = "Ein wenig Geduld\nEinzigartig (5)\nBenutzen: Stellt allen Gnomenarbeitern Schlangenöl zur Verfügung, wodurch sich ihre Arbeitsgeschwindigkeit 60 Sek. lang um 50% des Grundwerts erhöht. Bis zu 3-mal stapelbar. 1 Sek. Abklingzeit." }
entries[92471] = { ["name"] = "Jubekas Tagebuch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Dieses lädierte, in Leder gebundene Notizbuch hat schon bessere Zeiten gesehen.\"\n<Zum Lesen rechtsklicken>" }
entries[92472] = { ["name"] = "Durchweichtes Tagebuch", ["text"] = "Ein wenig Geduld\nEinzigartig\n\"Die Wahrscheinlichkeit, dies hier zu finden, kann nicht mehr als eins zu einer Million sein.\"" }
entries[92474] = { ["name"] = "Besonders schmalzige Allianzohren", ["text"] = "Questgegenstand\n\"Zündmines patentierte Glücksohren. Nur echt mit dem Schmalzpfropfen!\"" }
entries[92475] = { ["name"] = "\"Neue\" und \"verbesserte\" Infrarot-Hitzebrille", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Neue und verbesserte Infrarottechnologie! Entdeckt Infiltratoren, bevor sie Euch entdecken!\n\"Von 'neu' und 'verbessert' ist hier wenig zu erkennen.\"" }
entries[92484] = { ["name"] = "Versiegeltes Schreiben", ["text"] = "Questgegenstand\n\"Sieht unglaublich unspektakulär aus.\"" }
entries[92493] = { ["name"] = "Bilgewässer Sprengkapsel", ["text"] = "Questgegenstand\n\"Großartig zum Sprengen!\"" }
entries[92494] = { ["name"] = "Höllenfeuerfragment", ["text"] = "Questgegenstand" }
entries[92495] = { ["name"] = "Nethersturmfragment", ["text"] = "Questgegenstand\nBenutzen: Ruft die im Seelenstein gespeicherte Erinnerung ab. (30 Sek. Abklingzeit)" }
entries[92496] = { ["name"] = "Schergratfragment", ["text"] = "Questgegenstand\nBenutzen: Ruft die im Seelenstein gespeicherte Erinnerung ab. (30 Sek. Abklingzeit)" }
entries[92497] = { ["name"] = "Schattenmondfragment", ["text"] = "Questgegenstand\nBenutzen: Ruft die im Seelenstein gespeicherte Erinnerung ab. (30 Sek. Abklingzeit)" }
entries[92499] = { ["name"] = "Starke Nadel", ["text"] = "Questgegenstand\n\"Diese solide Nadel verströmt den wohltuenden Duft von Kiefern.\"" }
entries[92501] = { ["name"] = "Eine Nachricht von Chen Sturmbräu", ["text"] = "Questgegenstand\n\"Ich habe einen Eurer Verbündeten entdeckt – er ist schwer verletzt. Ich bitte Euch, so schnell wie möglich nach Binan zu kommen.\"" }
entries[92510] = { ["name"] = "Vol'jins Ruhestein", ["text"] = "Questgegenstand\nBenutzen: Bringt Euch zum Höhlenbau in Durotar zurück. Kann nur in der Nähe von Vol'jin in Binan verwendet werden." }
entries[92522] = { ["name"] = "Großes Belobigungsabzeichen der Klaxxi", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Schaltet einen Rufzuwachsbonus von 100% bei den Klaxxi frei. Gilt für sämtliche Charaktere Eurer Kriegsmeute.\nBenötigt Die Klaxxi\n- Respektvoll" }
entries[92523] = { ["name"] = "Götterglocke", ["text"] = "Questgegenstand\n\"Ihr filigranes Äußeres straft ihre Moguherkunft Lügen.\"" }
entries[92525] = { ["name"] = "Umprogrammierter Ausgrabungsbot", ["text"] = "Einzigartig (5)\nBenutzen: Ruft einen Ausgrabungsbot herbei, der an Eurer Seite kämpft. Funktioniert nur in der Krasarangwildnis. (1 Min Abklingzeit)" }
entries[92526] = { ["name"] = "Kiste mit Bannern der Horde", ["text"] = "Benutzen: Platziert eine Kiste mit Bannern für Hordecharaktere in der Herrschaftsfeste. Hält 20 Min. lang an." }
entries[92527] = { ["name"] = "Nagerkiste", ["text"] = "Benutzen: Platziert eine Nagetierkiste für Hordecharaktere in der Herrschaftsfeste. Hält 20 Min. lang an." }
entries[92528] = { ["name"] = "Obelisk der Täuschung", ["text"] = "Benutzen: Platziert einen Obelisken der Täuschung für Hordecharaktere in der Herrschaftsfeste. Hält 20 Min. lang an." }
entries[92530] = { ["name"] = "Kiste mit umprogrammierten Ausgrabungsbots", ["text"] = "Benutzen: Platziert eine Kiste mit umprogrammierten Ausgrabungsbots für Hordecharaktere in der Herrschaftsfeste. Hält 20 Min. lang an." }
entries[92531] = { ["name"] = "Kiste mit Allianzbannern", ["text"] = "Benutzen: Platziert eine Kiste mit Bannern für Allianzcharaktere in der Löwenlandung. Hält 20 Min. lang an." }
entries[92532] = { ["name"] = "Nagerkiste", ["text"] = "Benutzen: Platziert eine Nagetierkiste für Allianzcharaktere in der Löwenlandung. Hält 20 Min. lang an." }
entries[92533] = { ["name"] = "Obelisk der Täuschung", ["text"] = "Benutzen: Platziert einen Obelisken der Täuschung für Allianzcharaktere in der Löwenlandung. Hält 20 Min. lang an." }
entries[92535] = { ["name"] = "Kiste mit umprogrammierten Ausgrabungsbots", ["text"] = "Benutzen: Platziert eine Kiste mit umprogrammierten Ausgrabungsbots für Allianzcharaktere in der Löwenlandung. Hält 20 Min. lang an." }
entries[92538] = { ["name"] = "Blindgänger", ["text"] = "Ein wenig Geduld\nEinzigartig (5)\nBenutzen: Zusätzliche Munition verleiht den Zwergenarbeitern Zuversicht, wodurch sich ihre Arbeitsgeschwindigkeit permanent um 30% des Grundwerts erhöht. Bis zu 3-mal stapelbar." }
entries[92539] = { ["name"] = "Ungezähmter Bern", ["text"] = "Questgegenstand\n\"In diesem gehärteten Glanzstück aus dem Schwanz eines wilden Bernskorpions glüht ein inneres Feuer.\"" }
entries[92550] = { ["name"] = "Gefälschte Schriftrolle", ["text"] = "\"Enthält eine Bestellung für Talbukfleisch.\"\nVerkaufspreis:" }
entries[92553] = { ["name"] = "Gnomische Röntgenbrille", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[92556] = { ["name"] = "Verstärkter Seelenkern", ["text"] = "Der Schwarze Tempel\nWird beim Aufheben gebunden\n\"Dieser Gegenstand strotzt nur so vor arkaner Energie.\"" }
entries[92557] = { ["name"] = "Das Metallbräu", ["text"] = "Questgegenstand\n\"Der Geschmack dieses Bräus, das die Hitze eines sengenden Ofens mit soliden, strengen Erdtönen kombiniert, ist wahrlich einmalig.\"" }
entries[92560] = { ["name"] = "Hammerkopf", ["text"] = "Questgegenstand\n\"Diesem genial entworfenen Metallkopf sieht man sein Alter fast nicht an. Ihn zieren einige Essensspuren aus der Zeit, als er von den Ho-zen als Esstisch verwendet wurde.\"" }
entries[92561] = { ["name"] = "Hammergriff", ["text"] = "Questgegenstand\n\"Generationen von Häuptlingen der Ho-zen haben diesen kunstvollen Stiel als ein Symbol der Macht weitergereicht.\"" }
entries[92562] = { ["name"] = "Harmonische Salbe", ["text"] = "Questgegenstand\n\"Ihr spürt fast, wie das Öl unter Eurer Berührung singt, wie seine Konsistenz unter Euren Fingern schwingt und Euch ein Gefühl der Ruhe und Entspanntheit gibt.\"" }
entries[92563] = { ["name"] = "Das Auge des Sturms", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Dieser Kristall der Naaru verfügt über immense Kraft.\"" }
entries[92580] = { ["name"] = "Duftendes Parfüm", ["text"] = "Wird beim Aufheben gebunden\n\"Scheint das eine oder andere Goldstück wert zu sein.\"" }
entries[92581] = { ["name"] = "Duftendes Parfüm", ["text"] = "Wird beim Aufheben gebunden\n\"Betörend, doch vertraut...\"\nVerkaufspreis:" }
entries[92582] = { ["name"] = "Billiges Duftwasser", ["text"] = "Wird beim Aufheben gebunden\n\"Kann vermutlich gegen ein paar Silberstücke verscherbelt werden.\"" }
entries[92583] = { ["name"] = "Billiges Duftwasser", ["text"] = "Wird beim Aufheben gebunden\n\"Ein erträglicher Geruch, doch er verweilt zu lange in der Luft.\"\nVerkaufspreis:" }
entries[92584] = { ["name"] = "Kostbarer Rubin", ["text"] = "Wird beim Aufheben gebunden\n\"Sieht ziemlich wertvoll aus...\"" }
entries[92585] = { ["name"] = "Kostbarer Rubin", ["text"] = "Wird beim Aufheben gebunden\n\"Das Funkeln verbirgt seinen wahren Reiz.\"\nVerkaufspreis:" }
entries[92586] = { ["name"] = "Funkelnder Saphir", ["text"] = "Wird beim Aufheben gebunden\n\"Der hier scheint die eine oder andere Münze wert zu sein...\"" }
entries[92587] = { ["name"] = "Funkelnder Saphir", ["text"] = "Wird beim Aufheben gebunden\n\"Das Funkeln verbirgt seinen wahren Reiz.\"\nVerkaufspreis:" }
entries[92588] = { ["name"] = "Jadekätzchenfigur", ["text"] = "Wird beim Aufheben gebunden\n\"Dafür wird jemand einiges springen lassen...\"" }
entries[92589] = { ["name"] = "Jadekätzchenfigur", ["text"] = "Wird beim Aufheben gebunden\n\"Als Ihr sie aufhobt, zerbrach sie unbegreiflicherweise.\"\nVerkaufspreis:" }
entries[92590] = { ["name"] = "Rubinhalskette", ["text"] = "Wird beim Aufheben gebunden\n\"Ein paar Münzen wert...\"" }
entries[92591] = { ["name"] = "Rubinhalskette", ["text"] = "Wird beim Aufheben gebunden\n\"Der blutrote Stein funkelt im Licht.\"\nVerkaufspreis:" }
entries[92592] = { ["name"] = "Zaubersteinhalskette", ["text"] = "Wird beim Aufheben gebunden\n\"Etliche Münzen wert...\"" }
entries[92593] = { ["name"] = "Zaubersteinhalskette", ["text"] = "Wird beim Aufheben gebunden\n\"Der kalte, blaue Stein surrt, wenn man ihn hält.\"\nVerkaufspreis:" }
entries[92594] = { ["name"] = "Diamantring", ["text"] = "Wird beim Aufheben gebunden\n\"Ist nicht mehr so viel wert wie früher einmal...\"" }
entries[92595] = { ["name"] = "Diamantring", ["text"] = "Wird beim Aufheben gebunden\n\"Billig, funkelt aber.\"\nVerkaufspreis:" }
entries[92596] = { ["name"] = "Rubinring", ["text"] = "Wird beim Aufheben gebunden\n\"Einen ordentlichen Preis wert...\"" }
entries[92597] = { ["name"] = "Rubinring", ["text"] = "Wird beim Aufheben gebunden\n\"Der edelste Blutelfenschmuck wurde von jeher aus Rubinen hergestellt.\"\nVerkaufspreis:" }
entries[92598] = { ["name"] = "Goldring", ["text"] = "Wird beim Aufheben gebunden\n\"Ein paar Münzen wert...\"" }
entries[92599] = { ["name"] = "Goldring", ["text"] = "Wird beim Aufheben gebunden\n\"Massives Gold. Schockierend!\"\nVerkaufspreis:" }
entries[92600] = { ["name"] = "Kleiner Haufen Goldmünzen", ["text"] = "Wird beim Aufheben gebunden\n\"Ein kleiner Haufen Goldmünzen...\"" }
entries[92601] = { ["name"] = "Kleiner Haufen Goldmünzen", ["text"] = "Wird beim Aufheben gebunden\n\"Diese kleinen Münzen sind nur einige wenige Goldstücke wert, für einen Sammler könnten sie aber kostbar sein.\"\nVerkaufspreis:" }
entries[92602] = { ["name"] = "Großer Haufen Goldmünzen", ["text"] = "Wird beim Aufheben gebunden\n\"Ein großer Haufen Goldmünzen...\"" }
entries[92603] = { ["name"] = "Großer Haufen Goldmünzen", ["text"] = "Wird beim Aufheben gebunden\n\"Schon allein die schiere Menge an Münzen macht hier den Wert aus.\"\nVerkaufspreis:" }
entries[92604] = { ["name"] = "Goldener Kelch", ["text"] = "Wird beim Aufheben gebunden\n\"Ein paar Münzen wert...\"" }
entries[92605] = { ["name"] = "Goldener Kelch", ["text"] = "Wird beim Aufheben gebunden\n\"Aus irgendeinem Grund seid Ihr ziemlich stolz auf Euch, während Ihr ihn haltet.\"\nVerkaufspreis:" }
entries[92606] = { ["name"] = "Goldene Hochelfenstatuette", ["text"] = "Wird beim Aufheben gebunden\n\"Unglaublich wertvoll...\"" }
entries[92607] = { ["name"] = "Goldene Hochelfenstatuette", ["text"] = "Wird beim Aufheben gebunden\n\"Ihre Anmut und Gestalt kommen in diesem zeitlosen Stück gut zur Geltung.\"\nVerkaufspreis:" }
entries[92608] = { ["name"] = "Goldtrank", ["text"] = "Wird beim Aufheben gebunden\n\"Ein, zwei Goldstücke wert...\"" }
entries[92609] = { ["name"] = "Goldtrank", ["text"] = "Wird beim Aufheben gebunden\n\"Auf dem Etikett steht: Maximiert Eure Männlichkeit und beweist ihr, dass Ihr echtes Gold wert seid.\"\nVerkaufspreis:" }
entries[92610] = { ["name"] = "Goldteller", ["text"] = "Wird beim Aufheben gebunden\n\"Ein paar Goldstücke wert...\"" }
entries[92611] = { ["name"] = "Goldteller", ["text"] = "Wird beim Aufheben gebunden\n\"Schwer zu sagen, ob es sich hier um Geschirr oder eine Paladinrüstung handelt...\"\nVerkaufspreis:" }
entries[92612] = { ["name"] = "Zenas ausgesprochen ergiebiges Garnknäuel", ["text"] = "Wird beim Aufheben gebunden\n\"Einiges an Münzen wert...\"" }
